function validateValueField(fieldName, fieldValue, parameterIndex, bitValue) {
    switch (fieldName) {
        case "color":
            if (
                typeof fieldValue !== "object" ||
                !Array.isArray(fieldValue) ||
                fieldValue.length !== 4
            ) {
                throw new Error(
                    `Parameter at index ${parameterIndex} has value entry for bit "${bitValue}" with invalid type for field "${fieldName}". Expected array of four numbers.`
                );
            }
            break;
        case "label":
            if (typeof fieldValue !== "string") {
                throw new Error(
                    `Parameter at index ${parameterIndex} has value entry for bit "${bitValue}" with invalid type for field "${fieldName}". Expected string.`
                );
            }
            break;
        default:
            throw new Error(
                `Parameter at index ${parameterIndex} has value entry for bit "${bitValue}" with unknown field "${fieldName}".`
            );
    }
}

function validateParameterValues(values, parameterIndex) {
    const requiredValuesFields = ["color", "label"];

    if (typeof values !== "object" || values === null) {
        throw new Error(
            `Parameter at index ${parameterIndex} has invalid type for field "values". Expected object.`
        );
    }

    // Check each value entry
    for (const [bitValue, info] of Object.entries(values)) {
        if (typeof info !== "object" || info === null) {
            throw new Error(
                `Parameter at index ${parameterIndex} has invalid type for field "values". Expected object.`
            );
        }

        requiredValuesFields.forEach((vField) => {
            if (!(vField in info)) {
                throw new Error(
                    `Parameter at index ${parameterIndex} has value entry for bit "${bitValue}" missing required field "${vField}".`
                );
            }

            validateValueField(vField, info[vField], parameterIndex, bitValue);
        });
    }
}

function validateMappingAndParameters() {
    if (
        Object.keys(bitFlagParameterMapping).length !== bitFlagParameters.length
    ) {
        throw new Error(
            "Bit flag parameter mapping length does not match bit flag parameters length"
        );
    }

    // Check that all mapping keys correspond to existing parameter definitions
    const mappingKeys = Object.keys(bitFlagParameterMapping).map((k) =>
        parseInt(k)
    );

    // Check for duplicate keys (shouldn't happen but good to verify)
    if (new Set(mappingKeys).size !== mappingKeys.length) {
        throw new Error("Bit flag parameter mapping contains duplicate keys");
    }

    // Verify that each mapping entry has a corresponding parameter definition
    for (const [key, name] of Object.entries(bitFlagParameterMapping)) {
        const parameterExists = bitFlagParameters.some(
            (param) => param.name === name
        );
        if (!parameterExists) {
            throw new Error(
                `Bit flag parameter mapping key ${key} references parameter "${name}" which does not exist in bitFlagParameters`
            );
        }
    }

    const requiredParameterFields = ["name", "firstBit", "bitCount", "values"];

    // Each parameter in bitFlagParameters should have valid structure
    bitFlagParameters.forEach((param, index) => {
        if (!param || typeof param !== "object") {
            throw new Error(`Invalid parameter at index ${index}`);
        }
        // now add checks for required fields: they should exist and be of correct type

        requiredParameterFields.forEach((field) => {
            if (!(field in param)) {
                throw new Error(
                    `Parameter at index ${index} is missing required field "${field}"`
                );
            }

            switch (field) {
                case "name":
                    if (typeof param.name !== "string") {
                        throw new Error(
                            `Parameter at index ${index} has invalid type for field "${field}". Expected string.`
                        );
                    }
                    break;
                case "firstBit":
                case "bitCount":
                    if (
                        typeof param[field] !== "number" ||
                        !Number.isInteger(param[field]) ||
                        param[field] < 0
                    ) {
                        throw new Error(
                            `Parameter at index ${index} has invalid type for field "${field}". Expected non-negative integer.`
                        );
                    }
                    break;
                case "values":
                    validateParameterValues(param.values, index);
                    break;
                default:
                    throw new Error(
                        `Parameter at index ${index} has unknown field "${field}".`
                    );
            }
        });
    });
}

// Run validation once during script initialization
validateMappingAndParameters();

function evaluatePixel(sample) {
    if (!(selectedParameterIndex in bitFlagParameterMapping)) {
        throw new Error(
            `Selected flag index ${selectedParameterIndex} is not defined in bitFlagParameterMapping`
        );
    }

    // Find the corresponding parameter in bitFlagParameters array
    // We need to find which array index corresponds to our selected parameter
    let parameterArrayIndex = -1;
    for (let i = 0; i < bitFlagParameters.length; i++) {
        if (
            bitFlagParameters[i].name ===
            bitFlagParameterMapping[selectedParameterIndex]
        ) {
            parameterArrayIndex = i;
            break;
        }
    }

    if (parameterArrayIndex === -1) {
        throw new Error(
            `Could not find parameter definition for selected flag index ${selectedParameterIndex}`
        );
    }

    const selectedParameters = bitFlagParameters[parameterArrayIndex];

    var value =
        (sample.QAFLAGS >> selectedParameters.firstBit) &
        ((1 << selectedParameters.bitCount) - 1);

    for (const [bitValue, info] of Object.entries(selectedParameters.values)) {
        if (value == bitValue) {
            const color = info.color;
            if (sample.dataMask === 0) {
                // return transparent for masked pixels
                return [0, 0, 0, 0];
            } else {
                return [color[0], color[1], color[2], color[3]];
            }
        }
    }

    const selectedFlagName = bitFlagParameterMapping[selectedParameterIndex];
    throw new Error(
        `Value ${value} not defined for flag "${selectedFlagName}"`
    );
}

