function evaluatePixel(samples) {
  if (samples.dataMask == 0) return [0,0,0,0];

  var ndvi = index(samples.B4, samples.B1);

  if (ndvi<-0.2) return [0.75,0.75,0.75,1];
  else if (ndvi<-0.1) return [0.86,0.86,0.86,1];
  else if (ndvi<0) return [1,1,0.88,1];
