    2: "Potentially misclassified pixels reclassified by post-processing to improve performances",
};

function setup() {
    return {
        input: ["QAFLAGS", "dataMask"],
        output: {
            bands: 4,
            sampleType: "UINT8",
        },
    };
}
function hexToRgb(hex) {
    // Expected format: #AARRGGBB ["#ff6464d7"] or #RRGGBB ["#fff014"]
    if (!hex || typeof hex !== "string") {
        throw new Error("Invalid hex color format");
    }
    hex = hex.replace(/^#/, "");
    // Parse the components based on format
    if (hex.length === 6) {
        // Format: RRGGBB
        const r = parseInt(hex.substring(0, 2), 16);
        const g = parseInt(hex.substring(2, 4), 16);
        const b = parseInt(hex.substring(4, 6), 16);
        return [r, g, b, 1];
    } else if (hex.length === 8) {
        // Format: AARRGGBB
        const a = parseInt(hex.substring(0, 2), 16);
        const r = parseInt(hex.substring(2, 4), 16);
        const g = parseInt(hex.substring(4, 6), 16);
        const b = parseInt(hex.substring(6, 8), 16);
        return [r, g, b, a];
    } else {
        throw new Error("Invalid hex color format");
    }
}
const bitFlagParameters = [
    {
        name: "Hillshade",
        bitCount: 1,
        firstBit: 0,
        values: {
