function validateColorArray(fieldValue, parameterIndex, bitValue, context) {
    if (
        typeof fieldValue !== "object" ||
        !Array.isArray(fieldValue) ||
        fieldValue.length !== 4
    ) {
        throw new Error(
            `Parameter at index ${parameterIndex} has value entry for bit "${bitValue}" with invalid color${context}. Expected array of four numbers.`
        );
    }
}

function validateBit9Values(bit9Values, parameterIndex, bitValue) {
    if (typeof bit9Values !== "object" || bit9Values === null) {
        throw new Error(
            `Parameter at index ${parameterIndex} has value entry for bit "${bitValue}" with invalid bit9Values. Expected object.`
        );
    }
    for (const bit9Val of [0, 1]) {
        if (!(bit9Val in bit9Values)) {
            throw new Error(
                `Parameter at index ${parameterIndex} has value entry for bit "${bitValue}" missing bit9Values entry for bit9=${bit9Val}.`
            );
        }
        const entry = bit9Values[bit9Val];
        if (typeof entry !== "object" || entry === null) {
            throw new Error(
                `Parameter at index ${parameterIndex} has invalid bit9Values entry for bit9=${bit9Val}. Expected object.`
            );
        }
        if (!("color" in entry)) {
            throw new Error(
                `Parameter at index ${parameterIndex} has bit9Values entry for bit9=${bit9Val} missing required field "color".`
            );
        }
        validateColorArray(
            entry.color,
            parameterIndex,
            bitValue,
            ` in bit9Values[${bit9Val}]`
        );
        if (!("label" in entry) || typeof entry.label !== "string") {
            throw new Error(
                `Parameter at index ${parameterIndex} has bit9Values entry for bit9=${bit9Val} missing or invalid field "label". Expected string.`
            );
        }
    }
}

function validateValueField(fieldName, fieldValue, parameterIndex, bitValue) {
    switch (fieldName) {
        case "color":
            validateColorArray(fieldValue, parameterIndex, bitValue, "");
            break;
        case "label":
            if (typeof fieldValue !== "string") {
                throw new Error(
                    `Parameter at index ${parameterIndex} has value entry for bit "${bitValue}" with invalid type for field "${fieldName}". Expected string.`
                );
            }
            break;
        case "bit9Values":
            validateBit9Values(fieldValue, parameterIndex, bitValue);
            break;
        default:
            throw new Error(
                `Parameter at index ${parameterIndex} has value entry for bit "${bitValue}" with unknown field "${fieldName}".`
            );
    }
}

function validateParameterValues(values, parameterIndex) {
    const requiredValuesFields = ["color", "label"];
    if (typeof values !== "object" || values === null) {
        throw new Error(
