        );
    }
    for (const [bitValue, info] of Object.entries(values)) {
        if (typeof info !== "object" || info === null) {
            throw new Error(
                `Parameter at index ${parameterIndex} has invalid type for field "values". Expected object.`
            );
        }
        if ("bit9Values" in info) {
            validateValueField(
