function evaluatePixel(sample) {
    if (!(selectedParameterIndex in bitFlagParameterMapping)) {
        throw new Error(
            `Selected flag index ${selectedParameterIndex} is not defined in bitFlagParameterMapping`
        );
    }
    let parameterArrayIndex = -1;
    for (let i = 0; i < bitFlagParameters.length; i++) {
        if (
