    const mappingKeys = Object.keys(bitFlagParameterMapping).map((k) =>
        parseInt(k)
    );

    // Check for duplicate keys (shouldn't happen but good to verify)
    if (new Set(mappingKeys).size !== mappingKeys.length) {
        throw new Error("Bit flag parameter mapping contains duplicate keys");
    }

    // Verify that each mapping entry has a corresponding parameter definition
    for (const [key, name] of Object.entries(bitFlagParameterMapping)) {
        const parameterExists = bitFlagParameters.some(
            (param) => param.name === name
        );
        if (!parameterExists) {
            throw new Error(
                `Bit flag parameter mapping key ${key} references parameter "${name}" which does not exist in bitFlagParameters`
            );
        }
    }

    const requiredParameterFields = ["name", "firstBit", "bitCount", "values"];

