validateMappingAndParameters();

function evaluatePixel(sample) {
    if (!(selectedParameterIndex in bitFlagParameterMapping)) {
        throw new Error(
            `Selected flag index ${selectedParameterIndex} is not defined in bitFlagParameterMapping`
        );
    }

    // Find the corresponding parameter in bitFlagParameters array
    // We need to find which array index corresponds to our selected parameter
    let parameterArrayIndex = -1;
    for (let i = 0; i < bitFlagParameters.length; i++) {
        if (
            bitFlagParameters[i].name ===
            bitFlagParameterMapping[selectedParameterIndex]
        ) {
            parameterArrayIndex = i;
            break;
        }
    }

    if (parameterArrayIndex === -1) {
        throw new Error(
            `Could not find parameter definition for selected flag index ${selectedParameterIndex}`
        );
    }

    const selectedParameters = bitFlagParameters[parameterArrayIndex];

    var value =
        (sample.QAFLAGS >> selectedParameters.firstBit) &
        ((1 << selectedParameters.bitCount) - 1);

    for (const [bitValue, info] of Object.entries(selectedParameters.values)) {
        if (value == bitValue) {
            const color = info.color;
            if (sample.dataMask === 0) {
                // return transparent for masked pixels
                return [0, 0, 0, 0];
            } else {
                return [color[0], color[1], color[2], color[3]];
            }
        }
    }

    const selectedFlagName = bitFlagParameterMapping[selectedParameterIndex];
    throw new Error(
        `Value ${value} not defined for flag "${selectedFlagName}"`
    );
}

