function evaluatePixel(samples) {
    const originalValue = samples.ICD_QA;
    const val = originalValue * factor + offset;
    const min = 0;
    const max = 3;
    const stats = val >= min && val <= max ? val : NaN;
    const dataMask = samples.dataMask;

    const EXCLUDED_VALUES = [];
    const isExcluded =
        dataMask === 0 || EXCLUDED_VALUES.includes(originalValue);

    if (isExcluded) {
        return {
            default: [0, 0, 0, 0],
            index: [NaN],
            browserStats: [NaN],
            dataMask: [dataMask],
        };
    }

    const imgVals = getColor(val);
    return {
        default: [imgVals[0], imgVals[1], imgVals[2], dataMask * imgVals[3]],
        index: [val],
        browserStats: [stats],
        dataMask: [dataMask],
    };
}

