// Set up input and output settings
function setup() {
    return {
      input: [{
        bands: [
          "Change",
          "dataMask"
        ]
      }],
      output: [
          { id: "default", bands: 4 }, 
          //{ id: "browserStats", bands: 1, sampleType: 'FLOAT32' }, 
          { id: "dataMask", bands: 1 }
        ], 
    }
  }

  // Create color map for imperviousness change
  const ramps = [
    [0, 0x036600],   // 100% imperviousness decrease
    [50, 0x3FB200],  // 50% imperviousness decrease
    [99, 0x7FFF00],  // 1% imperviousness decrease
    [100, 0xB2B2B2], // sealed in both years (stable built-up)
    [101, 0xFFFF00], // 1% imperviousness increase
    [150, 0xFFBF00], // 50% imperviousness increase
    [200, 0xFF0000], // 100% imperviousness increase
  ];

  // Create visualiser
  const visualizer = new ColorRampVisualizer(ramps);

  //EvaluatePixel function
  function evaluatePixel(samples) {
    let val = samples.Change;
    let imgVals = visualizer.process(val);

    // Handle special values that are outside the ramp
    if (val == 201) {
      imgVals = [240, 240, 240, 255]; // #F0F0F0 - non sealed in both years (stable non-built up)
    } else if (val == 254) {
      imgVals = [168, 0, 229, 255];   // #A800E5 - unclassifiable (no satellite image available, or clouds, shadows, or snow)
    } else if (val == 255) {
      imgVals = [0, 0, 0, 255];       // #000000 - outside area
    } else {
      // Use the color ramp and add alpha channel
      imgVals = imgVals.concat(samples.dataMask * 255);
    }

    return {
      default: imgVals,
      //browserStats: [val],
      dataMask: [samples.dataMask]
     };
  }

