const factor = 1;
const offset = 0;

function setup() {
  return {
    input: ["day_of_burn", "dataMask"],
    output: [
      { id: "default", bands: 4, sampleType: "UINT8" },
      { id: "index", bands: 1, sampleType: "FLOAT32" },
